pub enum OutputWrap {
    Character,
    None,
}

#[derive(Clone)]
pub struct OutputComponents(pub HashSet<OutputComponent>);

pub enum PagerLaunch {
    Stdout,
    Process {
        path: PathBuf,
        args: Vec<String>,
        is_less: bool,
    },
}

pub struct CliRuntime {
    interactive_output: bool,
    cache_args_required: bool,
    skip_config: bool,
    merged_args: Vec<OsString>,
    paging_mode: PagingMode,
    pager: Option<String>,
    replace_less_arguments: bool,
    requested_styles: Vec<String>,
    decorations_never: bool,
    number_flag: bool,
    plain_flag: bool,
    plain_occurrences: u64,
    colored_output: bool,
    true_color: bool,
    theme_name: String,
    italic_text: bool,
    language_column_width: usize,
    listing_desired_width: usize,
    term_width: usize,
    tab_width: usize,
    loop_through: bool,
    show_nonprintable: bool,
    cache_blank: bool,
}

impl CliRuntime {
    pub fn new(interactive_output: bool) -> Self {
        CliRuntime {
            interactive_output,
            cache_args_required: !Path::new("cache").exists(),
            skip_config: false,
            merged_args: Vec::new(),
            paging_mode: PagingMode::Never,
            pager: None,
            replace_less_arguments: false,
            requested_styles: Vec::new(),
            decorations_never: false,
            number_flag: false,
            plain_flag: false,
            plain_occurrences: 0,
            colored_output: interactive_output,
            true_color: false,
            theme_name: String::from(BAT_THEME_DEFAULT),
            italic_text: false,
            language_column_width: 0,
            listing_desired_width: 0,
            term_width: 0,
            tab_width: 4,
            loop_through: false,
            show_nonprintable: false,
            cache_blank: false,
        }
    }

    pub fn build_clap_app(&self) -> ClapApp<'static, 'static> {
    let clap_color_setting = self.colorize_help();

    // Check if the current directory contains a file name cache, if it does
    // do not make the arguements for subcommand 'cache' required.
